const items = $input.all();

const datosUsuario = $("When Executed by Another Workflow").first().json;

const fechas = items.map(item => item.json.fecha);

const formato = new Intl.DateTimeFormat("es-CO", {
  timeZone: "America/Bogota",
  weekday: "long",
  day: "numeric",
  month: "long",
  year: "numeric",
  hour: "numeric",
  minute: "2-digit",
  hour12: true
});

const opciones = fechas.map((fecha, index) => {
  const fechaFormateada = formato.format(new Date(fecha));
  return `${index + 1}. ${fechaFormateada}`;
});

const mensaje =
  "¡Tenemos estos horarios disponibles para tu cita!\n\n" +
  opciones.join("\n") +
  "\n\nPor favor, responde con el número de la opción que prefieres (" +
  opciones.map((_, index) => index + 1).join(", ") +
  ").";

return [
  {
    json: {
      mensaje,
      celular: datosUsuario.celular,
      mensaje_original: datosUsuario.mensaje,
      id_vacante: datosUsuario.id_vacante,
      bot: datosUsuario.bot,
      opciones: fechas.map((fecha, index) => ({
        indice: index + 1,
        fecha
      }))
    }
  }
];

