const items = $input.all();

const datosUsuario = $("When Executed by Another Workflow").first().json;

// Obtener los horarios disponibles
const horarios = items.map(item => item.json);

const formatoFecha = new Intl.DateTimeFormat("es-CO", {
  timeZone: "America/Bogota",
  weekday: "long",
  day: "numeric",
  month: "long",
  year: "numeric"
});

// Convertir hora de 24 horas a formato de 12 horas
function formatearHora(hora) {
  const [horas, minutos] = hora.split(":").map(Number);

  const fecha = new Date();
  fecha.setHours(horas, minutos, 0, 0);

  return new Intl.DateTimeFormat("es-CO", {
    hour: "numeric",
    minute: "2-digit",
    hour12: true
  }).format(fecha);
}

const fechaFormateada = horarios.length
  ? formatoFecha.format(new Date(horarios[0].fecha))
  : "";

const opciones = horarios.map((horario, index) => {
  return `${index + 1}. ${formatearHora(horario.hora)}`;
});

const mensaje =
  `¡Tenemos estos horarios disponibles para tu cita el ${fechaFormateada}!\n\n` +
  opciones.join("\n") +
  "\n\nPor favor, responde con el número de la opción que prefieres (" +
  opciones.map((_, index) => index + 1).join(", ") +
  ").";

return [
  {
    json: {
      mensaje,
      celular: datosUsuario.celular,
      mensaje_original: datosUsuario.mensaje,
      id_vacante: datosUsuario.id_vacante,
      bot: datosUsuario.bot,
      opciones: horarios.map((horario, index) => ({
        indice: index + 1,
        id_horario: horario.id,
        fecha: horario.fecha,
        hora: horario.hora,
        cupos: horario.cupos
      }))
    }
  }
];

